#!/usr/bin/env bash
# Writes random secrets for a local Langfuse, starts it, and points the app at
# it. Safe to run again: existing secrets and keys are kept. Prints no secret.
set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
app_env="$here/../../.env"
env_file="$here/.env"

if [[ ! -f "$env_file" ]]; then
  hex() { openssl rand -hex "$1"; }
  pg_password="$(hex 16)"
  minio_password="$(hex 16)"
  umask 077
  cat > "$env_file" <<EOF
# Local Langfuse secrets, generated by setup.sh. Not committed.
LANGFUSE_IMAGE_TAG=4.76.0
TELEMETRY_ENABLED=false
NEXTAUTH_SECRET=$(hex 32)
SALT=$(hex 32)
ENCRYPTION_KEY=$(hex 32)
POSTGRES_PASSWORD=$pg_password
DATABASE_URL=postgresql://postgres:$pg_password@postgres:5432/postgres
CLICKHOUSE_PASSWORD=$(hex 16)
REDIS_AUTH=$(hex 16)
MINIO_ROOT_PASSWORD=$minio_password
LANGFUSE_S3_EVENT_UPLOAD_SECRET_ACCESS_KEY=$minio_password
LANGFUSE_S3_MEDIA_UPLOAD_SECRET_ACCESS_KEY=$minio_password
LANGFUSE_S3_BATCH_EXPORT_SECRET_ACCESS_KEY=$minio_password
# First user, organization, project and API keys, created at first start.
LANGFUSE_INIT_ORG_ID=retail-analyst
LANGFUSE_INIT_ORG_NAME=Retail Analyst
LANGFUSE_INIT_PROJECT_ID=retail-analyst
LANGFUSE_INIT_PROJECT_NAME=retail-analyst
LANGFUSE_INIT_PROJECT_PUBLIC_KEY=pk-lf-$(hex 16)
LANGFUSE_INIT_PROJECT_SECRET_KEY=sk-lf-$(hex 16)
LANGFUSE_INIT_USER_EMAIL=admin@retail-analyst.local
LANGFUSE_INIT_USER_NAME=Admin
LANGFUSE_INIT_USER_PASSWORD=$(hex 12)
EOF
  echo "Wrote $env_file"
fi

value() { grep "^$1=" "$env_file" | cut -d= -f2-; }
touch "$app_env"
if ! grep -q '^LANGFUSE_SECRET_KEY=.' "$app_env"; then
  sed -i '' -E '/^LANGFUSE_(PUBLIC_KEY|SECRET_KEY|HOST)=/d' "$app_env"
  [[ -s "$app_env" && -n "$(tail -c1 "$app_env")" ]] && echo >> "$app_env"
  {
    echo "LANGFUSE_PUBLIC_KEY=$(value LANGFUSE_INIT_PROJECT_PUBLIC_KEY)"
    echo "LANGFUSE_SECRET_KEY=$(value LANGFUSE_INIT_PROJECT_SECRET_KEY)"
    echo "LANGFUSE_HOST=http://localhost:3000"
  } >> "$app_env"
  echo "Added the Langfuse keys to $app_env"
fi

docker compose -f "$here/docker-compose.yml" --env-file "$env_file" up -d
echo "Waiting for Langfuse at http://localhost:3000 ..."
for _ in $(seq 60); do
  curl -fs http://localhost:3000/api/public/health > /dev/null && break
  sleep 5
done
curl -fs http://localhost:3000/api/public/health > /dev/null || { echo "Langfuse did not start; see: docker compose -f $here/docker-compose.yml logs langfuse-web"; exit 1; }
echo "Langfuse is up. Sign in as $(value LANGFUSE_INIT_USER_EMAIL); the password is LANGFUSE_INIT_USER_PASSWORD in $env_file."
